const pairs = [['搜索用户支付金额','搜索用户支付金额'],['搜索订单量','搜索订单量'],['搜索曝光人数','搜索结果曝光人数'],['搜索点击率','搜索点击率'],['搜索点击成交率','搜索点击成交率']];
const text = (document.body.innerText || '').replace(/\s+/g, ' ');
const items = [];
for (const [needle, label] of pairs) {
  const at = text.indexOf(needle);
  if (at < 0) continue;
  const seg = text.slice(at + needle.length, at + needle.length + 24);
  const hit = seg.match(/[0-9]+(?:\.[0-9]+)?/);
  if (!hit) continue;
  items.push({ label: label, today: hit[0], yesterday: '' });
}
return JSON.stringify({ asOf: new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10), items: items });
